import 'package:flutter/cupertino.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:zan/Core/Utils/Extensions/widget_extension.dart';import '../../../Favorite/presentation/pages/favorite_screen.dart';import '../../../User/presentation/pages/user_screen.dart';import '../../../Explore/presentation/pages/explore_srceen.dart';import '../../../Home/presentation/pages/home_page.dart';class MainCubit extends Cubit<int> {  MainCubit() : super(0);  void changeIndex(int index) {    emit(index);  }  Widget listScreens() {    Widget widget(int index) => Center(          child: Text(index.toString()),        );    switch (state) {      case 0:        return HomePage().stylePages2;      case 1:        return ExploreScreen().stylePagesInMain;      case 2:        return widget(444);      case 3:        return FavoriteScreen().stylePagesInMain;      case 4:        return UserScreen().stylePagesInMain;      default:        return widget(444);    }  }}